482		}
483	
484		r.note(id, func(f *Forward) {
485			f.Active++
486			f.Total++
487		})
488		defer r.note(id, func(f *Forward) { f.Active-- })
489	
490		failed := false
491		proxy := &httputil.ReverseProxy{
492			Rewrite: func(pr *httputil.ProxyRequest) {
493				pr.SetURL(&url.URL{Scheme: "http", Host: pr.In.Context().Value(targetKey{}).(string)})
494				// The inbound Host is kept: an application behind a named route
495				// often keys on it, and SetURL would replace it with the target's.
496				pr.Out.Host = pr.In.Host
497				pr.SetXForwarded()
498			},
499			Transport: routeTransport,
500			ErrorHandler: func(w http.ResponseWriter, req *http.Request, err error) {
501				failed = true
502				if req.Context().Err() != nil {
503					// The client went away — a cancelled navigation, a closed tab.
504					// That is not the route failing, and there is nobody to answer.
505					return
506				}
507				r.note(id, func(f *Forward) { f.LastErr = err.Error() })
508				w.Header().Set("Content-Type", "text/plain; charset=utf-8")
509				w.Header().Set("X-Content-Type-Options", "nosniff")
510				w.WriteHeader(http.StatusBadGateway)
511				_, _ = fmt.Fprintf(w, "%s did not answer.\n\n%v\n", target, err)
512			},
513		}
514		proxy.ServeHTTP(w, req.WithContext(context.WithValue(req.Context(), targetKey{}, target)))

